<template>
  <div class="patrol-mobile">
    <header class="topbar">
      <button v-if="loggedIn && view !== 'list'" class="icon-button" type="button" @click="goBack">‹</button>
      <div class="brand"><span class="brand-mark">巡</span><span>现场巡查</span></div>
      <button v-if="loggedIn" class="text-button" type="button" @click="logout">退出</button>
    </header>

    <main v-if="!loggedIn" class="body login-body">
      <section class="card login-card">
        <div class="eyebrow">华设集团 · 项目审批系统</div>
        <h1>巡查员登录</h1>
        <p class="muted">使用小程序巡查账号，任务与现场数据实时同步。</p>
        <form @submit.prevent="login">
          <label>账号<input v-model.trim="credentials.username" autocomplete="username" placeholder="请输入账号" required></label>
          <label>密码<input v-model="credentials.password" type="password" autocomplete="current-password" placeholder="请输入密码" required></label>
          <button class="primary full" type="submit" :disabled="busy">{{ busy ? '登录中…' : '登录' }}</button>
        </form>
      </section>
    </main>

    <main v-else class="body">
      <template v-if="view === 'list'">
        <div class="welcome"><div class="eyebrow">我的现场任务</div><h1>你好，{{ username }}</h1><p>下拉刷新或点击刷新，查看最新指派与整改进度。</p></div>
        <div class="stats"><div><strong>{{ total }}</strong><span>任务总数</span></div><div><strong>{{ activeCount }}</strong><span>待办（已加载）</span></div><div><strong>{{ openHazards }}</strong><span>未闭环隐患（已加载）</span></div></div>
        <div class="section-head"><h2>任务列表</h2><button class="text-button" type="button" :disabled="busy" @click="loadTasks(true)">刷新</button></div>
        <div v-if="!tasks.length && !busy" class="card empty">暂无任务</div>
        <button v-for="item in tasks" :key="item.task_id" class="card task-card" type="button" @click="navigate('detail', item.task_id)">
          <div class="between"><span class="mono">{{ item.task_no }}</span><span class="pill" :class="item.status">{{ taskStatus(item.status) }}</span></div>
          <h3>{{ item.name || '巡查任务' }}</h3>
          <p>{{ item.line || '未指定线路' }} · {{ item.location_desc || '未指定位置' }}</p>
          <div class="between small"><span>{{ fmt(item.created_at || item.dispatch_time) }}</span><span v-if="item.open_hazard_count">未闭环隐患 {{ item.open_hazard_count }} 个</span></div>
        </button>
        <button v-if="tasks.length < total" class="secondary full" type="button" :disabled="busy" @click="loadTasks(false)">加载更多</button>
      </template>

      <template v-else-if="view === 'detail'">
        <div v-if="!task" class="card empty">{{ busy ? '正在加载任务…' : '任务未找到' }}</div>
        <template v-else>
          <section class="card"><div class="between"><span class="mono">{{ task.task_no }}</span><span class="pill" :class="task.status">{{ taskStatus(task.status) }}</span></div><h1 class="detail-title">{{ task.name }}</h1><p class="meta"><b>线路</b>{{ task.line || '—' }}</p><p class="meta"><b>位置</b>{{ task.location_desc || '—' }}</p><p class="meta"><b>派发人</b>{{ task.dispatcher || '—' }}</p></section>
          <section v-if="task.requirement" class="card accent-card"><h2>巡查要求</h2><p class="preserve">{{ task.requirement }}</p></section>
          <section v-if="task.review_opinion || (task.docs || []).length" class="card"><h2>监测方案</h2><p v-if="task.review_opinion" class="preserve">{{ task.review_opinion }}</p><div v-for="doc in task.docs || []" :key="doc.doc_id" class="doc-row"><span>{{ doc.file_name }}</span><button class="link" type="button" @click="openDoc(doc, false)">查看</button><button class="link" type="button" @click="openDoc(doc, true)">下载</button></div></section>
          <section v-if="(task.opinions || []).length" class="card"><div class="section-head"><h2>审核意见现场核查（{{ task.opinions.length }}）</h2><button class="link" type="button" @click="opinionsOpen = !opinionsOpen">{{ opinionsOpen ? '收起' : '展开' }}</button></div><template v-if="opinionsOpen"><article v-for="op in task.opinions" :key="op.opinion_id" class="opinion"><div class="between"><strong>{{ op.title || '审核意见' }}</strong><span class="pill">{{ opinionStatus(op.status) }}</span></div><p class="small muted">{{ op.stage_name || '' }} {{ fmt(op.check_time || op.created_at) }}</p><p class="preserve">{{ op.opinion_content }}</p><p v-if="op.return_reason" class="notice">退回原因：{{ op.return_reason }}</p><p v-if="op.check_opinion" class="notice">核查意见：{{ op.check_opinion }}</p><div class="media-grid"><div v-for="photo in op.photos || []" :key="photo.photo_id" class="media-cell"><img v-if="assets['op:'+photo.photo_id]" :src="assets['op:'+photo.photo_id]" alt="现场照片" @click="previewAsset('op:'+photo.photo_id, 'image')"><span v-else class="media-placeholder" @click="previewAsset('op:'+photo.photo_id, 'image')">照片</span><button v-if="op.status !== 'done'" class="remove" type="button" aria-label="删除照片" @click="deleteOpinionPhoto(photo.photo_id)">×</button></div></div><div v-if="op.status !== 'done'" class="action-row"><button class="secondary" type="button" @click="choose('opinion', 'photo', op.opinion_id)">＋上传照片</button><button class="secondary" type="button" @click="choose('opinion', 'camera', op.opinion_id)">拍照</button><button v-if="op.status === 'pending_photo' || op.status === 'returned'" class="secondary" type="button" @click="submitOpinion(op)">提交核查</button></div></article></template></section>
          <section class="card"><div class="section-head"><h2>巡查时间线</h2><div><button class="link" type="button" @click="loadTask(task.task_id)">刷新</button><button v-if="canWrite" class="link" type="button" @click="navigate('hazard', task.task_id)">＋隐患</button></div></div><p v-if="!timeline.length" class="muted">暂无巡查记录</p><article v-for="entry in timeline" :key="entry.key" class="timeline-item"><div class="timeline-head"><span class="pill" :class="entry.kind">{{ entry.kind === 'record' ? (entry.data.type === 'rectify' ? '整改反馈' : '日常巡查') : '风险隐患' }}</span><strong v-if="entry.data.title">{{ entry.data.title }}</strong><span class="small muted">{{ entry.data.created_by_name || '—' }} · {{ fmt(entry.time) }}</span></div><p v-if="entry.kind === 'record' && entry.data.note" class="preserve">{{ entry.data.note }}</p><div v-if="entry.kind === 'record'" class="media-grid"><div v-for="media in entry.data.media || []" :key="media.media_id" class="media-cell" @click="previewAsset('media:'+media.media_id, media.kind)"><img v-if="media.kind === 'photo' && assets['media:'+media.media_id]" :src="assets['media:'+media.media_id]" alt="巡查照片"><span v-else class="media-placeholder">{{ media.kind === 'video' ? '▶ 视频' : '照片' }}</span></div></div><div v-if="entry.kind === 'record' && entry.data.type === 'patrol' && canWrite" class="action-row"><button class="link" type="button" @click="navigate('hazard', task.task_id, { record: entry.data.record_id })">＋关联隐患</button></div><div v-for="hazard in entry.hazards" :key="hazard.hazard_id" class="hazard"><div class="between" @click="toggleHazard(hazard.hazard_id)"><div><span class="pill">{{ hazardStatus(hazard.status) }}</span><span v-if="hazard.risk_level" class="pill risk">{{ hazard.risk_level }}</span><span v-if="hazard.hazard_type" class="pill">{{ hazard.hazard_type }}</span></div><span class="small link">{{ expandedHazards[hazard.hazard_id] ? '收起' : '详情' }}</span></div><p class="preserve">{{ hazard.description }}</p><div v-if="expandedHazards[hazard.hazard_id]" class="hazard-detail"><div class="steps"><span v-for="(step, i) in hazardSteps" :key="step" :class="{ reached: i <= hazardSteps.indexOf(hazard.status) }">{{ hazardStatus(step) }}</span></div><p v-if="hazard.rectify_requirement" class="notice">整改要求：{{ hazard.rectify_requirement }}</p><p v-if="hazard.rectify_owner" class="muted small">整改责任人：{{ hazard.rectify_owner }}</p><div class="media-grid"><div v-for="shot in hazard.shots || []" :key="shot.shot_id" class="media-cell" @click="previewAsset('shot:'+shot.shot_id, 'image')"><img v-if="assets['shot:'+shot.shot_id]" :src="assets['shot:'+shot.shot_id]" alt="隐患截图"><span v-else class="media-placeholder">截图</span></div></div><div v-for="record in hazard.rectifyRecords" :key="record.record_id" class="rectify"><b>整改记录 · {{ fmt(record.created_at) }}</b><p v-if="record.note" class="preserve">{{ record.note }}</p><div class="media-grid"><div v-for="media in record.media || []" :key="media.media_id" class="media-cell" @click="previewAsset('media:'+media.media_id, media.kind)"><img v-if="media.kind === 'photo' && assets['media:'+media.media_id]" :src="assets['media:'+media.media_id]" alt="整改照片"><span v-else class="media-placeholder">{{ media.kind === 'video' ? '▶ 视频' : '照片' }}</span></div></div></div><p v-if="hazard.review_comment" class="notice">复核意见：{{ hazard.review_comment }}</p></div><div v-if="canWrite" class="action-row"><button v-if="hazard.status === 'pending_rectify' || hazard.status === 'rectifying'" class="secondary" type="button" @click="startQuickRectify(hazard)">整改图片上传</button><button v-if="hazard.status === 'rectifying'" class="secondary" type="button" @click="submitReview(hazard)">整改完成</button><button v-if="hazard.status === 'pending_confirm'" class="link" type="button" @click="navigate('hazard', task.task_id, { hazard: hazard.hazard_id })">修改</button><button v-if="hazard.status === 'pending_confirm'" class="link danger" type="button" @click="deleteHazard(hazard)">删除</button></div></div></article></section>
          <div v-if="canWrite" class="bottom-action"><button class="primary full" type="button" @click="navigate('upload', task.task_id)">＋ 上传照片 / 视频</button></div>
        </template>
      </template>

      <template v-else-if="view === 'upload' && task">
        <section class="card"><h1>现场上报</h1><p class="muted">{{ task.name }}</p><label>记录类型<select v-model="upload.type"><option value="patrol">日常巡查</option><option value="rectify">整改反馈</option></select></label><label v-if="upload.type === 'rectify'">关联隐患<select v-model="upload.hazardId"><option value="">请选择隐患</option><option v-for="h in rectifiableHazards" :key="h.hazard_id" :value="h.hazard_id">{{ h.description }}</option></select></label><label>本次上传名称<input v-model.trim="upload.title" maxlength="120" placeholder="选填"></label><label>备注<textarea v-model="upload.note" maxlength="1000" rows="3" placeholder="现场情况、位置补充说明"></textarea></label><div class="location-row"><div><b>现场定位</b><p class="small muted">{{ locationText }}</p></div><button class="secondary" type="button" :disabled="locating" @click="getLocation">{{ locating ? '定位中…' : '获取定位' }}</button></div><p v-if="!windowSecure" class="notice">手机网页定位须通过 HTTPS 地址访问，普通局域网 HTTP 地址无法定位。</p></section>
        <section class="card"><h2>照片 / 视频</h2><p class="small muted">最多 9 张照片、2 段视频；单张 20 MB、单段 50 MB / 60 秒。</p><div class="action-row"><button class="secondary" type="button" @click="choose('media', 'photo')">选择照片</button><button class="secondary" type="button" @click="choose('media', 'video')">选择视频</button><button class="secondary" type="button" @click="choose('media', 'camera')">拍照</button></div><div class="media-grid"><div v-for="(item, i) in upload.media" :key="item.url" class="media-cell"><img v-if="item.kind === 'photo'" :src="item.url" alt="待上传照片" @click="previewLocal(item)"><span v-else class="media-placeholder" @click="previewLocal(item)">▶ 视频</span><button class="remove" type="button" @click="removeLocal('media', i)">×</button></div></div></section>
        <section v-if="upload.type === 'patrol'" class="card"><label class="check"><input v-model="upload.hasHazard" type="checkbox">本次巡查发现隐患</label><template v-if="upload.hasHazard"><label>隐患描述<textarea v-model="upload.hazardDesc" maxlength="2000" rows="3" placeholder="描述发现的问题"></textarea></label><label>隐患类型<select v-model="upload.hazardType"><option value="">请选择（选填）</option><option v-for="item in hazardTypes" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>风险等级<select v-model="upload.riskLevel"><option value="">请选择（选填）</option><option v-for="item in risks" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><div class="action-row"><button class="secondary" type="button" @click="choose('uploadShots', 'photo')">＋ 隐患截图</button><button class="secondary" type="button" @click="choose('uploadShots', 'camera')">拍照</button></div><div class="media-grid"><div v-for="(item, i) in upload.shots" :key="item.url" class="media-cell"><img :src="item.url" alt="待上传截图" @click="previewLocal(item)"><button class="remove" type="button" @click="removeLocal('uploadShots', i)">×</button></div></div></template></section>
        <div class="bottom-action"><p v-if="busy" class="small muted">{{ progressLabel }} {{ progress }}%</p><button class="primary full" type="button" :disabled="busy" @click="submitUpload">{{ busy ? '上报中…' : '确认上报' }}</button></div>
      </template>

      <template v-else-if="view === 'hazard' && task">
        <section class="card"><h1>{{ hazardForm.id ? '修改隐患' : '登记隐患' }}</h1><p class="muted">{{ task.name }}</p><label>隐患描述<textarea v-model="hazardForm.description" maxlength="2000" rows="5" placeholder="请描述现场隐患"></textarea></label><label>隐患类型<select v-model="hazardForm.hazardType"><option value="">请选择（选填）</option><option v-for="item in hazardTypes" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>风险等级<select v-model="hazardForm.riskLevel"><option value="">请选择（选填）</option><option v-for="item in risks" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label v-if="!hazardForm.id">整改责任人<input v-model.trim="hazardForm.rectifyOwner" maxlength="120" placeholder="选填"></label></section>
        <section class="card"><h2>隐患截图</h2><div class="action-row"><button class="secondary" type="button" @click="choose('hazardShots', 'photo')">＋ 选择照片</button><button class="secondary" type="button" @click="choose('hazardShots', 'camera')">拍照</button></div><div class="media-grid"><div v-for="(item, i) in hazardForm.shots" :key="item.url" class="media-cell"><img :src="item.url" alt="待上传截图" @click="previewLocal(item)"><button class="remove" type="button" @click="removeLocal('hazardShots', i)">×</button></div></div><p v-if="hazardForm.id" class="small muted">原有截图保留；新选照片会追加。</p></section><div class="bottom-action"><p v-if="busy" class="small muted">{{ progressLabel }} {{ progress }}%</p><button class="primary full" type="button" :disabled="busy" @click="submitHazard">{{ busy ? '保存中…' : '保存隐患' }}</button></div>
      </template>
    </main>

    <input ref="photoInput" class="file-input" type="file" accept="image/*" multiple @change="onFiles($event, 'photo')">
    <input ref="cameraInput" class="file-input" type="file" accept="image/*" capture="environment" @change="onFiles($event, 'photo')">
    <input ref="videoInput" class="file-input" type="file" accept="video/mp4,video/quicktime,video/*" multiple @change="onFiles($event, 'video')">
    <div v-if="preview" class="preview" @click.self="closePreview"><button type="button" class="preview-close" @click="closePreview">×</button><img v-if="preview.kind !== 'video'" :src="preview.url" alt="照片预览"><video v-else :src="preview.url" controls playsinline autoplay></video></div>
    <div v-if="quick.visible" class="dialog-mask" @click.self="closeQuick"><div class="dialog card"><h2>整改图片上传</h2><p class="small muted">最多 9 张，每张不超过 20 MB。</p><div class="action-row"><button class="secondary" type="button" @click="choose('quick', 'photo')">＋ 选择照片</button><button class="secondary" type="button" @click="choose('quick', 'camera')">拍照</button></div><div class="media-grid"><div v-for="(item, i) in quick.files" :key="item.url" class="media-cell"><img :src="item.url" alt="待上传整改照片"><button class="remove" type="button" @click="removeLocal('quick', i)">×</button></div></div><label>整改备注<textarea v-model="quick.note" rows="3" maxlength="1000"></textarea></label><p v-if="busy" class="small muted">{{ progressLabel }} {{ progress }}%</p><div class="action-row"><button class="secondary" type="button" :disabled="busy" @click="closeQuick">取消</button><button class="primary" type="button" :disabled="busy || !quick.files.length" @click="submitQuick">{{ busy ? '上传中…' : '确认上传' }}</button></div></div></div>
    <div v-if="toast" class="toast" role="status">{{ toast }}</div>
  </div>
</template>

<script>
import { clearMobileSession, getMobileToken, getMobileUser, mobileBlob, mobileDelete, mobileGet, mobileLogin, mobilePost, mobileUpload, saveMobileSession } from './api'
import { locate } from './geo'

const TASK_STATUS = { pending: '待执行', executing: '执行中', completed: '已完成', closed: '已关闭' }
const HAZARD_STATUS = { pending_confirm: '待确认', pending_rectify: '待整改', rectifying: '整改中', pending_review: '待复核', closed: '已闭环' }
const OPINION_STATUS = { pending_photo: '待拍照', photo_taken: '已拍照·待核查', done: '已完成', returned: '退回重拍' }
const HAZARD_STEPS = ['pending_confirm', 'pending_rectify', 'rectifying', 'pending_review', 'closed']
const PHOTO_LIMIT = 20 * 1024 * 1024
const VIDEO_LIMIT = 50 * 1024 * 1024
const nowText = () => { const d = new Date(); const pad = n => String(n).padStart(2, '0'); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}` }
const parseTime = value => new Date(String(value || '').replace(' ', 'T')).getTime() || 0
const newUpload = () => ({ type: 'patrol', hazardId: '', title: '', note: '', media: [], hasHazard: false, hazardDesc: '', hazardType: '', riskLevel: '', shots: [] })
const newHazard = () => ({ id: '', recordId: '', description: '', hazardType: '', riskLevel: '', rectifyOwner: '', shots: [] })

export default {
  name: 'PatrolMobile',
  data() { return { credentials: { username: '', password: '' }, loggedIn: !!getMobileToken(), username: getMobileUser(), tasks: [], total: 0, page: 1, task: null, timeline: [], assets: {}, urls: [], assetGeneration: 0, loadSequence: 0, busy: false, locating: false, location: null, toast: '', toastTimer: null, progress: 0, progressLabel: '', upload: newUpload(), hazardForm: newHazard(), hazardTypes: [], risks: [], opinionsOpen: false, expandedHazards: {}, preview: null, picker: null, quick: { visible: false, hazardId: '', recordId: '', existingPhotos: 0, note: '', files: [] }, hazardSteps: HAZARD_STEPS } },
  computed: {
    view() { return this.$route.query.view || 'list' },
    windowSecure() { return window.isSecureContext },
    canWrite() { return this.task && ['pending', 'executing'].includes(this.task.status) },
    activeCount() { return this.tasks.filter(t => ['pending', 'executing'].includes(t.status)).length },
    openHazards() { return this.tasks.reduce((sum, t) => sum + Number(t.open_hazard_count || 0), 0) },
    rectifiableHazards() { return (this.task && this.task.hazards || []).filter(h => ['pending_rectify', 'rectifying'].includes(h.status)) },
    locationText() { return this.location ? `${this.location.latitude.toFixed(6)}, ${this.location.longitude.toFixed(6)} · 精度约 ${Math.round(this.location.accuracy)} 米` : '尚未获取定位' }
  },
  watch: { '$route.query': { handler(to, from) { if (from && from.view === 'upload' && to.view !== 'upload') { this.releaseLocal(this.upload.media); this.releaseLocal(this.upload.shots); this.upload = newUpload() } if (from && from.view === 'hazard' && to.view !== 'hazard') { this.releaseLocal(this.hazardForm.shots); this.hazardForm = newHazard() } if (this.loggedIn) this.routeChanged() }, deep: true } },
  created() { window.addEventListener('patrol-mobile-unauthorized', this.unauthorized); if (this.loggedIn) this.bootstrap() },
  beforeDestroy() { window.removeEventListener('patrol-mobile-unauthorized', this.unauthorized); this.revokeAssets(); this.releaseLocal(this.upload.media); this.releaseLocal(this.upload.shots); this.releaseLocal(this.hazardForm.shots); this.releaseLocal(this.quick.files); clearTimeout(this.toastTimer) },
  methods: {
    taskStatus: value => TASK_STATUS[value] || value || '—', hazardStatus: value => HAZARD_STATUS[value] || value || '—', opinionStatus: value => OPINION_STATUS[value] || value || '—',
    fmt(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '—' },
    flash(message) { this.toast = message; clearTimeout(this.toastTimer); this.toastTimer = setTimeout(() => { this.toast = '' }, message.length > 35 ? 7000 : 3600) },
    fail(error) { this.flash(error && error.message || '操作失败') },
    async login() { if (this.busy) return; this.busy = true; try { const result = await mobileLogin(this.credentials.username, this.credentials.password); if (!result.token) throw new Error('登录未返回令牌'); saveMobileSession(result.token, this.credentials.username); this.username = this.credentials.username; this.loggedIn = true; this.credentials.password = ''; await this.bootstrap() } catch (error) { this.fail(error) } finally { this.busy = false } },
    logout() { if (!window.confirm('确定退出登录吗？')) return; this.unauthorized() },
    unauthorized() { clearMobileSession(); this.loadSequence++; this.loggedIn = false; this.task = null; this.tasks = []; this.revokeAssets(); this.releaseLocal(this.upload.media); this.releaseLocal(this.upload.shots); this.releaseLocal(this.hazardForm.shots); this.releaseLocal(this.quick.files); this.upload = newUpload(); this.hazardForm = newHazard(); this.quick.visible = false; this.quick.files = []; this.$router.replace({ path: '/rail/patrol-mobile' }).catch(() => {}) },
    async bootstrap() { await Promise.all([this.loadTasks(true), this.loadDicts()]); await this.routeChanged() },
    navigate(view, taskId, extra = {}) { this.$router.push({ path: '/rail/patrol-mobile', query: { view, task: taskId, ...extra } }).catch(() => {}) },
    goBack() { if (this.view === 'detail') this.$router.push({ path: '/rail/patrol-mobile' }).catch(() => {}); else this.navigate('detail', this.$route.query.task) },
    async routeChanged() { const taskId = this.$route.query.task; if (!taskId || this.view === 'list') return; if (!this.task || this.task.task_id !== taskId || this.view === 'detail') await this.loadTask(taskId); if (!this.task || this.task.task_id !== taskId) return; if (this.view === 'upload') { this.releaseLocal(this.upload.media); this.releaseLocal(this.upload.shots); this.upload = newUpload(); this.location = null } if (this.view === 'hazard') { this.releaseLocal(this.hazardForm.shots); this.hazardForm = newHazard(); const id = this.$route.query.hazard; if (id) { const h = (this.task.hazards || []).find(item => item.hazard_id === id); if (h) this.hazardForm = { id, recordId: h.record_id || '', description: h.description, hazardType: h.hazard_type || '', riskLevel: h.risk_level || '', rectifyOwner: h.rectify_owner || '', shots: [] } } else this.hazardForm.recordId = this.$route.query.record || '' } },
    async loadTasks(reset) { if (this.busy && !reset) return; this.busy = true; try { const page = reset ? 1 : this.page + 1; const result = await mobileGet('/rail/patrol/tasks', { page, size: 30 }); this.tasks = reset ? (result.items || []) : this.tasks.concat(result.items || []); this.total = Number(result.total || this.tasks.length); this.page = page } catch (error) { this.fail(error) } finally { this.busy = false } },
    async loadDicts() { try { const [types, risks] = await Promise.all([mobileGet('/rail/patrol/dicts', { dictType: 'hazard_type' }), mobileGet('/rail/patrol/dicts', { dictType: 'hazard_risk' })]); this.hazardTypes = types || []; this.risks = risks || [] } catch (error) { this.fail(error) } },
    async loadTask(id) { const sequence = ++this.loadSequence; this.busy = true; try { const task = await mobileGet(`/rail/patrol/tasks/${encodeURIComponent(id)}`); if (sequence !== this.loadSequence) return; this.task = task; this.buildTimeline(task); this.revokeAssets(); const jobs = []; (task.records || []).forEach(r => (r.media || []).filter(m => m.kind === 'photo').forEach(m => jobs.push([`media:${m.media_id}`, `/rail/patrol/media/${m.media_id}/file`]))); (task.hazards || []).forEach(h => (h.shots || []).forEach(s => jobs.push([`shot:${s.shot_id}`, `/rail/patrol/shots/${s.shot_id}/file`]))); (task.opinions || []).forEach(o => (o.photos || []).forEach(p => jobs.push([`op:${p.photo_id}`, `/rail/patrol/opinion-photos/${p.photo_id}/file`]))); this.primeAssets(jobs, this.assetGeneration) } catch (error) { if (sequence === this.loadSequence) { this.task = null; this.fail(error) } } finally { if (sequence === this.loadSequence) this.busy = false } },
    buildTimeline(task) { const byId = {}; (task.hazards || []).forEach(h => { this.$set(h, 'rectifyRecords', []); byId[h.hazard_id] = h }); const entries = []; (task.records || []).forEach(r => { if (r.type === 'rectify' && byId[r.hazard_id]) byId[r.hazard_id].rectifyRecords.push(r); else entries.push({ key: r.record_id, kind: 'record', time: r.created_at, data: r, hazards: (task.hazards || []).filter(h => h.record_id === r.record_id) }) }); (task.hazards || []).filter(h => !h.record_id).forEach(h => entries.push({ key: h.hazard_id, kind: 'hazard', time: h.created_at, data: h, hazards: [h] })); entries.sort((a, b) => parseTime(b.time) - parseTime(a.time)); Object.values(byId).forEach(h => h.rectifyRecords.sort((a, b) => parseTime(a.created_at) - parseTime(b.created_at))); this.timeline = entries },
    toggleHazard(id) { this.$set(this.expandedHazards, id, !this.expandedHazards[id]) },
    async primeAssets(jobs, generation) { let next = 0; const worker = async () => { while (next < jobs.length && generation === this.assetGeneration) { const [key, path] = jobs[next++]; await this.fetchAsset(key, path, generation) } }; await Promise.all(Array.from({ length: Math.min(4, jobs.length) }, worker)) },
    async fetchAsset(key, path, generation = this.assetGeneration) { try { const blob = await mobileBlob(path); if (generation !== this.assetGeneration) return; const url = URL.createObjectURL(blob); this.$set(this.assets, key, url); this.urls.push(url) } catch (error) { /* 单张资源失败不影响任务阅读 */ } },
    revokeAssets() { this.assetGeneration++; this.urls.forEach(url => URL.revokeObjectURL(url)); this.urls = []; this.assets = {} },
    async previewAsset(key, kind) { try { if (!this.assets[key]) { const [type, id] = key.split(':'); const path = type === 'media' ? `/rail/patrol/media/${id}/file` : type === 'shot' ? `/rail/patrol/shots/${id}/file` : `/rail/patrol/opinion-photos/${id}/file`; await this.fetchAsset(key, path) } if (this.assets[key]) this.preview = { url: this.assets[key], kind } } catch (error) { this.fail(error) } },
    previewLocal(item) { this.preview = { url: item.url, kind: item.kind } }, closePreview() { this.preview = null },
    async openDoc(doc, download) { const tab = !download && doc.kind !== 'word' ? window.open('', '_blank') : null; try { const blob = await mobileBlob(`/rail/patrol/docs/${doc.doc_id}/file`); const url = URL.createObjectURL(blob); if (download || doc.kind === 'word' || !tab) { const anchor = document.createElement('a'); anchor.href = url; anchor.download = doc.file_name || '监测方案'; document.body.appendChild(anchor); anchor.click(); anchor.remove() } else tab.location.href = url; setTimeout(() => URL.revokeObjectURL(url), 60000) } catch (error) { if (tab) tab.close(); this.fail(error) } },
    async getLocation() { this.locating = true; try { this.location = await locate(); this.flash('定位成功') } catch (error) { this.fail(error) } finally { this.locating = false } },
    choose(scope, kind, id = '') { this.picker = { scope, id }; const ref = kind === 'camera' ? 'cameraInput' : kind === 'video' ? 'videoInput' : 'photoInput'; this.$refs[ref].click() },
    async onFiles(event, kind) { const files = Array.from(event.target.files || []); event.target.value = ''; if (!files.length || !this.picker) return; const { scope, id } = this.picker; this.picker = null; if (scope === 'opinion') { await this.uploadOpinionPhotos(id, files); return } const target = scope === 'media' ? this.upload.media : scope === 'uploadShots' ? this.upload.shots : scope === 'hazardShots' ? this.hazardForm.shots : this.quick.files; for (let file of files) { const photo = kind === 'photo'; const limit = scope === 'media' && !photo ? 2 : 9; const count = scope === 'media' ? target.filter(item => item.kind === kind).length : target.length + (scope === 'quick' ? this.quick.existingPhotos : 0); if (count >= limit) { this.flash(`每条记录最多${limit}${photo ? '张照片' : '段视频'}`); break } try { if (photo) file = await this.preparePhoto(file); else { if (!/\.(mp4|mov)$/i.test(file.name)) throw new Error('仅支持 MP4 或 MOV 视频'); if (file.size > VIDEO_LIMIT) throw new Error('单段视频不能超过 50 MB'); if (await this.videoTooLong(file)) throw new Error('视频不能超过 60 秒') } target.push({ file, url: URL.createObjectURL(file), kind }) } catch (error) { this.fail(error) } } },
    preparePhoto(file) { if (/\.(jpe?g|png|webp|bmp)$/i.test(file.name) && file.size <= PHOTO_LIMIT) return Promise.resolve(file); return new Promise((resolve, reject) => { const image = new Image(); const url = URL.createObjectURL(file); image.onload = () => { URL.revokeObjectURL(url); const scale = Math.min(1, 2400 / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); canvas.toBlob(blob => { if (!blob || blob.size > PHOTO_LIMIT) return reject(new Error('照片无法压缩到 20 MB 以下')); resolve(new File([blob], file.name.replace(/\.[^.]+$/, '') + '.jpg', { type: 'image/jpeg' })) }, 'image/jpeg', 0.85) }; image.onerror = () => { URL.revokeObjectURL(url); reject(new Error('浏览器不支持此照片格式，请选择 JPG 或 PNG')) }; image.src = url }) },
    videoTooLong(file) { return new Promise(resolve => { const video = document.createElement('video'); const url = URL.createObjectURL(file); let settled = false; const done = tooLong => { if (settled) return; settled = true; clearTimeout(timer); URL.revokeObjectURL(url); resolve(tooLong) }; const timer = setTimeout(() => done(false), 8000); video.preload = 'metadata'; video.onloadedmetadata = () => done(video.duration > 60); video.onerror = () => done(false); video.src = url }) },
    removeLocal(scope, index) { const target = scope === 'media' ? this.upload.media : scope === 'uploadShots' ? this.upload.shots : scope === 'hazardShots' ? this.hazardForm.shots : this.quick.files; const [item] = target.splice(index, 1); if (item) URL.revokeObjectURL(item.url) }, releaseLocal(items) { (items || []).forEach(item => URL.revokeObjectURL(item.url)) },
    setProgress(label, done, total, partial = 0) { this.progressLabel = label; this.progress = Math.round((done + partial / 100) / Math.max(total, 1) * 100) },
    async sendFiles(path, items, fields, start, total) { let done = start; for (const item of items) { this.setProgress(`正在上传 ${done + 1}/${total}`, done, total); await mobileUpload(path, item.file, { ...fields, ...(path.includes('/media') ? { kind: item.kind } : {}) }, p => this.setProgress(`正在上传 ${done + 1}/${total}`, done, total, p)); done++; this.setProgress(`已上传 ${done}/${total}`, done, total) } return done },
    async submitUpload() { if (this.busy) return; const form = this.upload; if (!form.media.length) return this.flash('请先选择照片或视频'); if (!this.location) return this.flash('请先获取定位'); if (form.type === 'rectify' && !form.hazardId) return this.flash('请选择关联隐患'); if (form.type === 'patrol' && form.hasHazard && !form.hazardDesc.trim()) return this.flash('请填写隐患描述'); this.busy = true; let created = false; try { const record = await mobilePost(`/rail/patrol/tasks/${this.task.task_id}/records`, { type: form.type, hazard_id: form.type === 'rectify' ? form.hazardId : '', title: form.title.trim(), note: form.note.trim(), ...this.location }); created = true; const total = form.media.length + (form.type === 'patrol' && form.hasHazard ? form.shots.length : 0); let done = await this.sendFiles(`/rail/patrol/records/${record.record_id}/media`, form.media, { takenAt: nowText() }, 0, total); if (form.type === 'patrol' && form.hasHazard) { const hazard = await mobilePost(`/rail/patrol/tasks/${this.task.task_id}/hazards`, { record_id: record.record_id, description: form.hazardDesc.trim(), hazard_type: form.hazardType, risk_level: form.riskLevel }); done = await this.sendFiles(`/rail/patrol/hazards/${hazard.hazard_id}/shots`, form.shots, {}, done, total) } this.flash('上报成功'); this.navigate('detail', this.task.task_id) } catch (error) { this.flash(`${error.message}${created ? '；部分数据可能已保存，请先返回任务详情核对，避免重复上报。' : ''}`) } finally { this.busy = false } },
    async submitHazard() { if (this.busy) return; const form = this.hazardForm; if (!form.description.trim()) return this.flash('请填写隐患描述'); this.busy = true; let saved = false; try { let hazard; const payload = { description: form.description.trim(), hazard_type: form.hazardType, risk_level: form.riskLevel }; if (form.id) hazard = await mobilePost(`/rail/patrol/hazards/${form.id}`, payload); else hazard = await mobilePost(`/rail/patrol/tasks/${this.task.task_id}/hazards`, { ...payload, record_id: form.recordId, rectify_owner: form.rectifyOwner }); saved = true; await this.sendFiles(`/rail/patrol/hazards/${hazard.hazard_id}/shots`, form.shots, {}, 0, form.shots.length); this.flash('隐患已保存'); this.navigate('detail', this.task.task_id) } catch (error) { this.flash(`${error.message}${saved ? '；隐患可能已保存，请先返回任务详情核对。' : ''}`) } finally { this.busy = false } },
    async deleteHazard(hazard) { if (!window.confirm('确认删除该隐患？')) return; try { await mobileDelete(`/rail/patrol/hazards/${hazard.hazard_id}`); this.flash('已删除'); await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } },
    currentRectifyRecord(hazard) { return (this.task.records || []).filter(r => r.type === 'rectify' && r.hazard_id === hazard.hazard_id && (!hazard.review_time || parseTime(r.created_at) > parseTime(hazard.review_time))).sort((a, b) => parseTime(b.created_at) - parseTime(a.created_at))[0] },
    startQuickRectify(hazard) { const record = this.currentRectifyRecord(hazard); this.quick = { visible: true, hazardId: hazard.hazard_id, recordId: record && record.record_id || '', existingPhotos: record ? (record.media || []).filter(m => m.kind === 'photo').length : 0, note: record && record.note || '', files: [] } },
    closeQuick() { if (this.busy) return; this.releaseLocal(this.quick.files); this.quick.visible = false; this.quick.files = [] },
    async submitQuick() { if (this.busy || !this.quick.files.length) return; this.busy = true; try { let id = this.quick.recordId; if (id) await mobilePost(`/rail/patrol/records/${id}`, { note: this.quick.note.trim() }); else { let position = null; try { position = await locate() } catch (error) { /* 快速整改允许无坐标，后端接收 null */ } const record = await mobilePost(`/rail/patrol/tasks/${this.task.task_id}/records`, { type: 'rectify', hazard_id: this.quick.hazardId, note: this.quick.note.trim(), longitude: position && position.longitude, latitude: position && position.latitude, accuracy: position && position.accuracy }); id = record.record_id } await this.sendFiles(`/rail/patrol/records/${id}/media`, this.quick.files, { kind: 'photo', takenAt: nowText() }, 0, this.quick.files.length); this.flash('整改照片已上传'); this.releaseLocal(this.quick.files); this.quick.visible = false; this.quick.files = []; await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } finally { this.busy = false } },
    async submitReview(hazard) { if (!window.confirm('确认整改已完成，提交平台复核？')) return; try { await mobilePost(`/rail/patrol/hazards/${hazard.hazard_id}/submit`); this.flash('已提交复核'); await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } },
    async uploadOpinionPhotos(id, files) { const opinion = (this.task.opinions || []).find(o => o.opinion_id === id); if (!opinion) return; if ((opinion.photos || []).length + files.length > 9) return this.flash('每条意见最多 9 张照片'); this.busy = true; try { for (let i = 0; i < files.length; i++) { const file = await this.preparePhoto(files[i]); this.setProgress(`上传现场照片 ${i + 1}/${files.length}`, i, files.length); await mobileUpload(`/rail/patrol/opinions/${id}/photos`, file, { takenAt: nowText() }, p => this.setProgress(`上传现场照片 ${i + 1}/${files.length}`, i, files.length, p)) } this.flash('照片已上传'); await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } finally { this.busy = false } },
    async deleteOpinionPhoto(id) { if (!window.confirm('确认删除该现场照片？')) return; try { await mobileDelete(`/rail/patrol/opinion-photos/${id}`); this.flash('照片已删除'); await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } },
    async submitOpinion(opinion) { if (!window.confirm('确认现场照片已拍好并提交平台核查？')) return; try { await mobilePost(`/rail/patrol/opinions/${opinion.opinion_id}/submit`); this.flash('已提交核查'); await this.loadTask(this.task.task_id) } catch (error) { this.fail(error) } }
  }
}
</script>

